styles:
.reader-quote {
  font-style: normal;
  color: #c9a96e;
  font-family: 'Courier New', 'Consolas', monospace;
  text-decoration: underline;
  text-decoration-style: dotted;
  text-underline-offset: 3px;
}
.reader-ellipsis {
  letter-spacing: 6px;
  color: #b8976a;
}
.reader-dash {
  letter-spacing: 4px;
  color: #9a7a4a;
  font-family: 'Courier New', monospace;
}
.reader-speak {
  color: #d4b87a;
  font-weight: 700;
  font-variant: small-caps;
  font-family: 'Courier New', monospace;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3em;
  line-height: 0.75;
  padding-right: 8px;
  padding-top: 4px;
  color: #b8976a;
  font-weight: 900;
  font-family: 'Courier New', monospace;
  border-bottom: 2px solid #b8976a;
}
